// Boulder Run toggle: A movie in a toggle. Flip it and the explorer outruns the boulder. Flip it back for the sequel.
// One file, no dependencies. From https://zerowing.in/toggles/
//
// Use it:
//   <script type="module" src="boulder.js"></script>
//
//   <tg-boulder style="display:block; width:360px; height:220px"></tg-boulder>
//
//   <script type="module">
//     const t = document.querySelector("tg-boulder");
//     t.addEventListener("change", (e) => console.log("on?", e.detail.checked));
//     // t.checked = true;  t.toggle();
//   </script>
//
// API: the `checked` attribute / .checked property, .toggle(), a "change" event ({detail: {checked}}).
// The switch scales to fit its box (designed at 360x220); fill="0.9" sets how much of the box it fills (default 0.82).
// The element paints its own scene background, so give it a rounded container if you want one.

// ---- shared base ----
// Shared base for every toggle in the library.
//
// Contract (every components/<id>.js follows it):
//   - `export default class extends ToggleBase` and `customElements.define('tg-<id>', …)` at the bottom.
//   - Override `template()` → HTML string for the shadow root (include its own <style>).
//     Everything is drawn inside a fixed design stage of W×H px (static W/H, default 360×220);
//     the base scales that stage to fit the host. The host itself is the full scene (paint
//     :host's background yourself if the style swaps day/night etc.).
//   - Override `render(on, instant)` → apply the on/off state. `instant` is true on first paint.
//   - Optional `tick(t, dt)` → called every animation frame while connected (t in ms, from
//     performance.now(), so a virtual clock can drive it). Return nothing.
//   - Any element with [data-hit] is the clickable switch; clicking it calls this.toggle().
//   - Time sources: only performance.now() / rAF / CSS transitions & animations. No setTimeout
//     chains for visible motion (capture seeks a virtual clock).
//
// Public API on every element: .checked (bool, reflects the `checked` attribute), .toggle(),
// 'change' event with detail {checked}. this.scale = current stage scale, this.dpr = devicePixelRatio.

class ToggleBase extends HTMLElement {
  static W = 360;
  static H = 220;
  static observedAttributes = ['checked'];

  constructor() {
    super();
    this.root = this.attachShadow({ mode: 'open' });
    this.scale = 1;
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this._raf = 0;
    this._last = 0;
  }

  template() { return ''; }
  render(_on, _instant) {}
  tick(_t, _dt) {}
  onResize() {}

  connectedCallback() {
    if (!this._built) {
      const { W, H } = this.constructor;
      this.root.innerHTML = `
        <style>
          :host { display: block; position: relative; overflow: hidden; contain: content; -webkit-tap-highlight-color: transparent; }
          .tg-stage { position: absolute; left: 50%; top: 50%; width: ${W}px; height: ${H}px;
            transform: translate(-50%, -50%) scale(var(--s, 1)); transform-origin: 50% 50%; }
          [data-hit] { cursor: pointer; }
        </style>
        <div class="tg-stage">${this.template()}</div>`;
      this.stage = this.root.querySelector('.tg-stage');
      this.root.addEventListener('click', (e) => {
        if (e.composedPath().some((n) => n instanceof Element && n.hasAttribute('data-hit'))) this.toggle();
      });
      this._built = true;
      this.setup?.();
      this.render(this.checked, true);
    }
    this._ro = new ResizeObserver(() => this._fit());
    this._ro.observe(this);
    this._fit();
    const loop = (t) => {
      const dt = this._last ? Math.min(t - this._last, 64) : 16;
      this._last = t;
      this.tick(t, dt);
      this._raf = requestAnimationFrame(loop);
    };
    this._raf = requestAnimationFrame(loop);
  }

  disconnectedCallback() {
    cancelAnimationFrame(this._raf);
    this._ro?.disconnect();
    this._last = 0;
  }

  _fit() {
    const { W, H } = this.constructor;
    const r = this.getBoundingClientRect();
    if (!r.width || !r.height) return;
    // Toggle fills ~78% of the shorter fit so every tile has breathing room.
    this.scale = Math.min(r.width / W, r.height / H) * (parseFloat(this.getAttribute('fill')) || 0.82);
    this.style.setProperty('--s', this.scale);
    this.onResize();
  }

  get checked() { return this.hasAttribute('checked'); }
  set checked(v) { this.toggleAttribute('checked', !!v); }

  attributeChangedCallback(name, oldV, newV) {
    if (name === 'checked' && this._built && (oldV === null) !== (newV === null)) {
      this.render(this.checked, false);
      this.dispatchEvent(new CustomEvent('change', { detail: { checked: this.checked }, bubbles: true }));
    }
  }

  toggle() { this.checked = !this.checked; }

  $(sel) { return this.root.querySelector(sel); }
  $$(sel) { return [...this.root.querySelectorAll(sel)]; }

  // Size a <canvas> to cover `w×h` design px at full device resolution.
  sizeCanvas(cv, w, h) {
    const k = this.scale * this.dpr;
    cv.width = Math.max(1, Math.round(w * k));
    cv.height = Math.max(1, Math.round(h * k));
    cv.style.width = w + 'px';
    cv.style.height = h + 'px';
    const ctx = cv.getContext('2d');
    ctx.setTransform(k, 0, 0, k, 0, 0);
    return ctx;
  }
}

// Easing helpers shared by components.
const ease = {
  outCubic: (x) => 1 - Math.pow(1 - x, 3),
  inOutCubic: (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2),
  outBack: (x, s = 1.70158) => 1 + (s + 1) * Math.pow(x - 1, 3) + s * Math.pow(x - 1, 2),
  // Critically-damped-ish spring step: returns new [pos, vel].
  spring: (pos, vel, target, dt, k = 170, d = 18) => {
    const s = dt / 1000;
    const a = -k * (pos - target) - d * vel;
    vel += a * s;
    pos += vel * s;
    return [pos, vel];
  },
};

const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));

// ---- Boulder Run ----
// Boulder Run — a little adventure movie inside a toggle.
// Off → On  = Scene 1 "The Idol": the explorer lifts the idol, the boulder (the knob) rolls, he sprints and dives out.
// On → Off  = Scene 2 "The Sequel": he walks back in and pushes the boulder all the way home, catches his hat,
//             puts the idol back and dusts off his hands.
// Everything is a pure function of scene time s, so any frame can be seeked. Clicking mid-scene fast-forwards
// the running scene, then plays the next one.

const TW = 300, TH = 130;          // inner window (design px) — matches Snow Globe
const BR = 56;                     // boulder radius (112 knob)
const BY = TH / 2;                 // boulder centre y
const G = BY + BR;                 // floor line
const LX = 9 + BR, RX = TW - 9 - BR; // boulder slots
const NX = 150;                    // niche / idol x
const NY = 66;                     // niche ledge top
const STX = LX + 79;               // where he stands after pushing the boulder home
const D1 = 2.35, D2 = 2.8;         // scene lengths (s)
const TAU = Math.PI * 2;
const EX = 1.75;                   // explorer scale (~58 px tall)
const KS = EX / 1.2;               // stride / spacing factor vs the original 1.2 rig
const HAT_A = -0.45;               // where the hat sits on the boulder (angle from top)
const TORCHES = [{ x: 75, y: 40 }, { x: 225, y: 40 }];

const hash = (i) => { const x = Math.sin(i * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); };
const seg = (s, a, b) => clamp((s - a) / (b - a));
const eo = ease.outCubic, eio = ease.inOutCubic;

// ---------- explorer poses ----------
// Angles are from straight down, positive = toward facing. legs: [thigh, knee bend], arms: [upper, elbow bend].
const P = (o) => Object.assign({
  x: NX, dir: 1, lean: 0.04, lift: 0, rot: 0, tilt: 0,
  legs: [[0.07, 0.06], [-0.07, 0.06]], arms: [[0.15, 0.3], [-0.1, 0.3]],
  hat: true, idol: false, mark: 0,
}, o);

function lerpPose(a, b, k) {
  const L = (u, v) => u + (v - u) * k;
  return {
    ...(k < 0.5 ? a : b),
    x: L(a.x, b.x), lean: L(a.lean, b.lean), lift: L(a.lift, b.lift), rot: L(a.rot, b.rot), tilt: L(a.tilt, b.tilt),
    legs: a.legs.map((l, i) => [L(l[0], b.legs[i][0]), L(l[1], b.legs[i][1])]),
    arms: a.arms.map((l, i) => [L(l[0], b.arms[i][0]), L(l[1], b.arms[i][1])]),
  };
}

const stand = (t, x = NX, dir = 1, o = {}) => P({
  x, dir, lift: 0.35 * Math.sin(t * 0.0024), tilt: 0.04 * Math.sin(t * 0.0013),
  arms: [[0.12 + 0.04 * Math.sin(t * 0.0024), 0.3], [-0.12, 0.3]], ...o,
});
const CROUCH = P({ lean: 0.24, lift: 2.6, legs: [[0.5, 1.0], [-0.02, 0.8]], arms: [[-0.4, 0.6], [-0.6, 0.5]], tilt: 0.12 });
const REACH = P({ lean: -0.06, lift: -1.5, legs: [[0.03, 0], [-0.03, 0]], arms: [[3.02, 0.04], [-0.3, 0.25]], tilt: -0.5 });
const HOLD = P({ lean: -0.1, lift: -0.4, legs: [[0.14, 0.1], [-0.1, 0.05]], arms: [[2.8, 0.15], [0.55, 2.0]], tilt: -0.25, idol: true });

const runLeg = (q) => [0.8 * Math.sin(q), 0.25 + 1.25 * Math.max(0, Math.cos(q))];
const pushLeg = (q) => [0.5 * Math.sin(q) - 0.38, 0.2 + 0.95 * Math.max(0, Math.cos(q))];
const walkLeg = (q) => [0.45 * Math.sin(q), 0.15 + 0.7 * Math.max(0, Math.cos(q))];

// Scene 1 — The Idol
function exp1(s, t) {
  const st = stand(t);
  if (s < 0.12) return st;
  if (s < 0.22) return lerpPose(st, CROUCH, eo(seg(s, 0.12, 0.22)));
  if (s < 0.36) return lerpPose(CROUCH, REACH, ease.outBack(seg(s, 0.22, 0.36), 1.3));
  if (s < 0.5) return { ...lerpPose(REACH, HOLD, eio(seg(s, 0.36, 0.5))), idol: true };
  if (s < 0.58) return { ...HOLD, tilt: -0.22 + 0.07 * Math.sin(s * 90) };
  if (s < 0.72) {
    const k = seg(s, 0.58, 0.72);
    return P({ dir: -1, lean: -0.28, lift: -7.5 * Math.sin(Math.PI * k), legs: [[0.6, 1.2], [-0.12, 0.95]],
      arms: [[2.6, 0.3], [2.15, 0.5]], tilt: -0.1, idol: true, mark: 1 });
  }
  if (s < 1.45) {
    const k = seg(s, 0.72, 1.45);
    const x = NX + 135 * Math.pow(k, 1.25);
    const ph = (x - NX) / (7.8 * KS) + 0.6;
    return P({ x, lean: 0.32, lift: 0.6 - 1.9 * Math.abs(Math.cos(ph)), legs: [runLeg(ph), runLeg(ph + Math.PI)],
      arms: [[1.15, 1.7], [-0.95 * Math.sin(ph) + 0.1, 1.25]], tilt: 0.05, idol: true, mark: s < 0.82 ? 1 : 0 });
  }
  if (s < 1.8) {
    const k = seg(s, 1.45, 1.8);
    return P({ x: 285 + 70 * k, lean: 0.3, rot: 1.25 * eo(Math.min(1, k * 1.5)),
      lift: -9 * Math.sin(Math.PI * k) + 8 * k * k, legs: [[-0.15, 0.3], [-0.5, 0.6]],
      arms: [[2.75, 0.05], [2.55, 0.1]], tilt: -0.3, idol: true, hat: s < 1.52 });
  }
  return null;
}

// Scene 2 — The Sequel
const PUSH_DX = 79;
function pushPose(x, o = {}) {
  const ph = (400 - x) / (6 * KS);
  return P({ x, dir: -1, lean: 0.78, lift: 1.4 + 0.8 * Math.abs(Math.sin(ph)), legs: [pushLeg(ph), pushLeg(ph + Math.PI)],
    arms: [[1.5, 0.15], [1.38, 0.3]], tilt: 0.22, hat: false, ...o });
}
function exp2(s, t, bx) {
  if (s < 0.3) {
    const k = seg(s, 0, 0.3);
    const x = bx + PUSH_DX + 40 * (1 - eo(k));
    return pushPose(x, { lean: 0.35 + 0.43 * k, arms: [[1.0 + 0.5 * k, 0.4], [0.8 + 0.58 * k, 0.5]] });
  }
  if (s < 1.6) return pushPose(bx + PUSH_DX);
  const STANDL = stand(t, STX, -1, { hat: false });
  if (s < 1.85) return lerpPose(pushPose(LX + PUSH_DX), STANDL, eo(seg(s, 1.6, 1.85)));
  const LOOK = P({ x: STX, dir: -1, hat: false, tilt: -0.6, lean: -0.1, arms: [[0.7, 0.9], [0.5, 0.9]] });
  if (s < 2.05) return lerpPose(STANDL, LOOK, eo(seg(s, 1.85, 1.97)));
  if (s < 2.17) {
    const k = seg(s, 2.05, 2.17);
    return { ...lerpPose(LOOK, STANDL, eo(k)), hat: true, lift: 2 * Math.sin(Math.PI * k) };
  }
  if (s < 2.4) {
    const k = eio(seg(s, 2.17, 2.4));
    const x = STX + (NX - STX) * k;
    const ph = k * 3 * Math.PI;
    return P({ x, legs: [walkLeg(ph), walkLeg(ph + Math.PI)], arms: [[-0.35 * Math.sin(ph), 0.35], [0.35 * Math.sin(ph), 0.35]],
      lift: 0.4 - 0.8 * Math.abs(Math.cos(ph)) });
  }
  const st = stand(t);
  if (s < 2.5) return { ...lerpPose(st, REACH, eo(seg(s, 2.4, 2.5))), idol: true };
  if (s < 2.62) return lerpPose(REACH, st, eio(seg(s, 2.5, 2.62)));
  if (s < 2.8) {
    const w = Math.sin(s * 70);
    const dust = P({ arms: [[0.95 + 0.14 * w, 1.3], [0.85 - 0.14 * w, 1.3]], tilt: 0.14, lean: 0.06 });
    return lerpPose(dust, st, seg(s, 2.74, 2.8));
  }
  return st;
}

// ---------- boulder ----------
function boulder1(s) {
  if (s < 0.44) return [LX, BY];
  if (s < 0.5) return [LX + 1.1 * Math.sin((s - 0.44) * 130), BY];
  if (s < 1.88) return [LX + (RX - LX) * Math.pow(seg(s, 0.5, 1.88), 1.15), BY];
  return [RX - 5 * Math.sin(Math.PI * seg(s, 1.88, 2.08)), BY - 2.5 * Math.sin(Math.PI * seg(s, 1.88, 2.0))];
}
function boulder2(s) {
  if (s < 0.3) return [RX, BY];
  if (s < 0.4) return [RX - 2.5 * Math.sin(Math.PI * seg(s, 0.3, 0.4)), BY];
  if (s < 1.6) {
    const u = eio(seg(s, 0.4, 1.6));
    const g = u - (Math.sin(TAU * 6 * u) / (TAU * 6)) * 0.75;   // surges, one per heave
    return [RX - (RX - LX) * g, BY];
  }
  return [LX, BY];
}

function headPos(p) {
  const hy = G + EX * (-14 + p.lift);
  const sx = 10 * Math.sin(p.lean), sy = -10 * Math.cos(p.lean);
  return [p.x + EX * p.dir * (sx + 5 * Math.sin(p.lean)), hy + EX * (sy - 5 * Math.cos(p.lean))];
}

// World state for a scene at time s. scene 0 = resting.
function world(scene, s, t) {
  const w = { shake: 0, idolNiche: false, hat: null, exp: null };
  if (scene === 1) {
    [w.bx, w.by] = boulder1(s);
    w.exp = exp1(s, t);
    w.idolNiche = s < 0.36;
    if (s < 0.44) w.shake = 0;
    else if (s < 0.82) w.shake = 0.9;
    if (s >= 1.88) w.shake = 3.4 * Math.exp(-(s - 1.88) * 10);
    if (s >= 1.52 && s < 2.1) {
      const tau = s - 1.52, T = 0.58, g = 700, y0 = 62, y1 = BY - BR * Math.cos(HAT_A), vy = (y1 - y0 - 0.5 * g * T * T) / T;
      const x1 = RX + BR * Math.sin(HAT_A);
      w.hat = { x: 298 + (x1 - 298) * (tau / T), y: y0 + vy * tau + 0.5 * g * tau * tau, rot: HAT_A - 2 * TAU * (1 - tau / T) };
    } else if (s >= 2.1) {
      const k = seg(s, 2.1, 2.35);
      w.hat = { x: w.bx + BR * Math.sin(HAT_A), y: w.by - BR * Math.cos(HAT_A) - 3 * Math.sin(Math.PI * k) * (1 - k), rot: HAT_A + 0.25 * Math.sin(k * 9) * (1 - k), squash: k < 0.2 ? 1 - k * 2 : 0 };
    }
  } else {
    [w.bx, w.by] = boulder2(s);
    w.exp = exp2(s, t, w.bx);
    w.idolNiche = s >= 2.5;
    w.shake = s > 0.4 && s < 1.6 ? 0.35 : 0;
    if (s < 1.72) {
      const pushing = s > 0.3 && s < 1.6 ? 1 : 0;
      w.hat = { x: w.bx + BR * Math.sin(HAT_A) + 1.5 * Math.sin(s * 9) * pushing, y: w.by - BR * Math.cos(HAT_A) - Math.abs(Math.sin(s * 13)) * 2.2 * pushing, rot: HAT_A + 0.2 * Math.sin(s * 7) * pushing };
    } else if (s < 2.05) {
      const k = eio(seg(s, 1.72, 2.05)), u = 1 - k;
      const hp = headPos(P({ x: STX, dir: -1 }));
      const p0 = [LX + BR * Math.sin(HAT_A), BY - BR * Math.cos(HAT_A)], p1 = [LX + 45, -10], p2 = [hp[0], hp[1] - 2.2 * EX];
      w.hat = { x: u * u * p0[0] + 2 * u * k * p1[0] + k * k * p2[0], y: u * u * p0[1] + 2 * u * k * p1[1] + k * k * p2[1], rot: HAT_A * (1 - k) + TAU * k };
    }
  }
  w.rot = (w.bx - LX) / BR;
  return w;
}

// ---------- drawing ----------
function drawHat(ctx, x, y, rot, sq = 0, sc = 1) {
  ctx.save();
  ctx.translate(x, y); ctx.rotate(rot); ctx.scale(sc * (1 + sq * 0.15), sc * (1 - sq * 0.2));
  ctx.fillStyle = '#7a4e2a';
  ctx.beginPath(); ctx.ellipse(0, 0, 6.2, 1.3, 0, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-3.6, 0); ctx.quadraticCurveTo(-3.8, -4.6, -0.6, -4.9); ctx.quadraticCurveTo(0, -4.2, 0.6, -4.9);
  ctx.quadraticCurveTo(3.8, -4.6, 3.6, 0); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#2a170b'; ctx.fillRect(-3.6, -1.6, 7.2, 1.2);
  ctx.fillStyle = 'rgba(255,220,170,.25)'; ctx.fillRect(-3, -4.2, 2.2, 0.7);
  ctx.restore();
}

function drawIdol(ctx, x, y, glint = 0, sc = 1) {
  ctx.save(); ctx.translate(x, y); ctx.scale(sc, sc);
  const g = ctx.createLinearGradient(-3, -11, 3, 0);
  g.addColorStop(0, '#fff2a8'); g.addColorStop(0.45, '#f2b632'); g.addColorStop(1, '#8a5a12');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.moveTo(-3, 0); ctx.lineTo(-2.2, -5.5); ctx.lineTo(2.2, -5.5); ctx.lineTo(3, 0); ctx.closePath(); ctx.fill();
  ctx.beginPath(); ctx.ellipse(0, -8.2, 2.6, 3, 0, 0, TAU); ctx.fill();
  ctx.fillStyle = '#5a3a0a'; ctx.fillRect(-1.3, -8.8, 0.8, 0.8); ctx.fillRect(0.5, -8.8, 0.8, 0.8);
  if (glint > 0) {
    ctx.globalAlpha = glint; ctx.fillStyle = '#fff';
    ctx.translate(1.5, -9);
    ctx.beginPath(); ctx.moveTo(0, -5); ctx.lineTo(0.7, -0.7); ctx.lineTo(5, 0); ctx.lineTo(0.7, 0.7); ctx.lineTo(0, 5);
    ctx.lineTo(-0.7, 0.7); ctx.lineTo(-5, 0); ctx.lineTo(-0.7, -0.7); ctx.closePath(); ctx.fill();
  }
  ctx.restore();
}

function drawExplorer(ctx, p) {
  // ground shadow
  const air = clamp(-p.lift / 14);
  ctx.fillStyle = `rgba(10,5,2,${0.45 * (1 - air * 0.6)})`;
  ctx.beginPath(); ctx.ellipse(p.x, G + 0.8, 7.5 * KS * (1 - air * 0.3), 2.2, 0, 0, TAU); ctx.fill();

  for (const outline of [true, false]) {
    ctx.save();
    ctx.translate(p.x, G); ctx.scale(EX * p.dir, EX); ctx.translate(0, -14 + p.lift); ctx.rotate(p.rot);
    ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    const O = outline ? 1.7 : 0;
    const col = (c) => (outline ? 'rgba(18,9,4,.9)' : c);
    const limb = (ax, ay, a1, a2, l1, l2, w, c) => {
      const kx = ax + l1 * Math.sin(a1), ky = ay + l1 * Math.cos(a1);
      const ex = kx + l2 * Math.sin(a2), ey = ky + l2 * Math.cos(a2);
      ctx.strokeStyle = col(c); ctx.lineWidth = w + O;
      ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(kx, ky); ctx.lineTo(ex, ey); ctx.stroke();
      return [ex, ey];
    };
    const sx = 10 * Math.sin(p.lean), sy = -10 * Math.cos(p.lean);
    const leg = ([th, kn], c) => {
      const a2 = th - kn;
      const [fx, fy] = limb(0, 0, th, a2, 7, 7, 3.3, c);
      ctx.strokeStyle = col('#24160c'); ctx.lineWidth = 3.3 + O;
      ctx.beginPath(); ctx.moveTo(fx, fy); ctx.lineTo(fx + 2.6 * Math.cos(a2), fy - 2.6 * Math.sin(a2)); ctx.stroke();
    };
    const arm = ([up, el], c, hasIdol) => {
      const [hx, hy] = limb(sx, sy + 1, up, up + el, 6.5, 6, 2.6, c);
      ctx.fillStyle = col('#e0a678');
      ctx.beginPath(); ctx.arc(hx, hy, 1.4 + O / 2, 0, TAU); ctx.fill();
      if (hasIdol && !outline) drawIdol(ctx, hx, hy + 1.5, 0);
    };
    arm(p.arms[1], '#a8875a', false);
    leg(p.legs[1], '#4e3220');
    // satchel
    ctx.fillStyle = col('#5a361b');
    ctx.save(); ctx.rotate(p.lean); ctx.beginPath(); ctx.roundRect(-5.2 - O / 2, -4.5 - O / 2, 4.2 + O, 4.6 + O, 1); ctx.fill(); ctx.restore();
    // torso
    ctx.strokeStyle = col('#d8b47a'); ctx.lineWidth = 5.4 + O;
