      ctx.beginPath(); ctx.moveTo(sx + 1.6 * Math.cos(p.lean), sy + 1.6 * Math.sin(p.lean)); ctx.lineTo(-2.2, -1.6); ctx.stroke();
      ctx.strokeStyle = '#6a4528'; ctx.lineWidth = 5.4;
      ctx.beginPath(); ctx.moveTo(0, 0.6); ctx.lineTo(0.6 * Math.sin(p.lean), -1.2); ctx.stroke();
    }
