    ctx.fillStyle = col('#e0a678');
    ctx.beginPath(); ctx.arc(0, 0, 3.8 + O / 2, 0, TAU); ctx.fill();
    if (!outline) {
      ctx.fillStyle = '#3a2412'; ctx.beginPath(); ctx.arc(-1.2, 0.6, 2.9, Math.PI * 0.55, Math.PI * 1.25); ctx.fill();
