          font: 700 9px/1 "Courier New", ui-monospace, monospace; letter-spacing: .2em; color: #ead9b6; white-space: nowrap; }
        .slate i { width: 22px; height: 11px; border-radius: 2px; background: repeating-linear-gradient(-45deg, #f3eee4 0 3px, #111 3px 6px);
          box-shadow: 0 0 0 1px rgba(0,0,0,.6); }
        .slate span { color: #f2b632; }
        .slate b { font-weight: 400; color: rgba(234,217,182,.7); }
      </style>
      <div class="slate"><i></i><span>SCENE 1</span><b>THE IDOL</b></div>
