      </div>`;
  }

  setup() {
    this.cv = this.$('canvas');
    this.slate = this.$('.slate');
    this.slateN = this.$('.slate span');
    this.slateT = this.$('.slate b');
    this.noise = buildNoise();
    this.scene = 0; this.s = 0; this.since = 99;
    this.pos = this.checked ? 1 : 0;
    this.target = this.pos;
  }

  onResize() {
    this.ctx = this.sizeCanvas(this.cv, TW, TH);
    this.k = this.scale * this.dpr;
    this.wall = buildWall(this.k);
    this.pats = this.noise.map((n) => this.ctx.createPattern(n, 'repeat'));
  }

  render(on, instant) {
    this.target = on ? 1 : 0;
    if (instant) { this.pos = this.target; this.scene = 0; }
  }

  tick(t, dt) {
    if (!this.scene && this.pos !== this.target) {
      this.scene = this.target ? 1 : 2; this.s = 0;
      this.slateN.textContent = this.scene === 1 ? 'SCENE 1' : 'SCENE 2';
      this.slateT.textContent = this.scene === 1 ? 'THE IDOL' : 'THE SEQUEL';
    }
