    ctx.globalCompositeOperation = 'source-over';

    // projector flicker + vignette
    ctx.fillStyle = `rgba(0,0,0,${0.03 + 0.05 * hash(Math.floor(t / 42))})`; ctx.fillRect(0, 0, TW, TH);
    const vg = ctx.createRadialGradient(TW / 2, TH / 2, 30, TW / 2, TH / 2, TW * 0.6);
    vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(0,0,0,.6)');
    ctx.fillStyle = vg; ctx.fillRect(0, 0, TW, TH);

    // film grain (device pixels)
    const fr = Math.floor(t / 42);
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalCompositeOperation = 'overlay'; ctx.globalAlpha = 0.09;
    const ox = hash(fr) * 128, oy = hash(fr + 1) * 128;
    ctx.translate(-ox, -oy); ctx.fillStyle = this.pats[fr % 4];
    ctx.fillRect(0, 0, this.cv.width + 128, this.cv.height + 128);
    ctx.setTransform(k, 0, 0, k, 0, 0);
    ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1;

  }
}

customElements.define('tg-boulder', Boulder);
